413	   413	                return;
414	   414	            }
415	   415	
416	   416	            sendNotifications(order, sale); // 알림 전송
417	   417	
418	   418	            // 3. Sale 상태 변경
419	   419	            sale.updateStatus(SaleStatus.SOLD);
